// Writes the browser + extension copies of functions/_lib/categories.js.
import { writeFileSync } from "node:fs";
import * as C from "../functions/_lib/categories.js";
const data = { departments: C.DEPARTMENTS, categories: C.CATEGORIES, sizes: C.SIZES, legacy: C.LEGACY };
const json = JSON.stringify(data);
writeFileSync(new URL("../assets/categories.js", import.meta.url),
  "/* GENERATED by scripts/gen-categories.mjs from functions/_lib/categories.js — do not edit. */\nwindow.FASH_CAT=" + json + ";\n");
writeFileSync(new URL("../apps/extension/config/categories.json", import.meta.url), json + "\n");
console.log("categories:", C.CATEGORIES.length, "departments:", C.DEPARTMENTS.length);
